import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source for batched matrix multiplication (naive)
bmm_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void bmm_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * m * n) {
        int b = idx / (m * n);
        int remainder = idx % (m * n);
        int i = remainder / n;
        int j = remainder % n;

        float sum = 0.0f;
        for (int l = 0; l < k; ++l) {
            int a_idx = b * m * k + i * k + l;
            int b_idx = b * k * n + l * n + j;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}

torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B) {
    auto batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    // Allocate output tensor on device
    auto out_tensor = torch::empty({batch_size, m, n}, type_torch::kFloat).cuda();
    float* out_ptr = out_tensor.data_ptr<float>();

    const int block_size = 256;
    const int num_blocks = (batch_size * m * n + block_size - 1) / block_size;

    bmm_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        out_ptr,
        batch_size, m, k, n
    );

    return out_tensor;
}
"""

# C++ function signature source (just declaration)
bmm_cpp_source = "torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B);"

# Define custom CUDA operator for batched matrix multiplication
bmm = load_inline(
    name="bmm",
    cpp_sources=bmm_cpp_source,
    cuda_sources=bmm_kernel_source,
    functions=["bmm_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.bmm = bmm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.bmm(A, B)
